(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c7-advanced-1"]={"id":"unit31-trap-c7-advanced-1","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 선지 변형 유형 · 정도","name":"심화 1","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"정도","parts":[{"name":"U31-P02-03-S1 · 정도","items":[{"paragraphCount":1,"readingLabel":"2문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 2문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 2문단]\n사랑은 또한 위험한 것이기도 하다. 많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다. 부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다. 연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다. 그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["정도"],"why":"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n근거: “연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.”\n2문단에서 확인할 수 있어요.","evidence":{"title":"연인에게 소유욕이 끼기 쉽다.","statement":"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.","explanation":"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n근거: “연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.”\n2문단에서 확인할 수 있어요.","valid":["R02:4"],"sources":[{"id":"R02","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"2문단","sentences":[{"id":"R02:1","text":"사랑은 또한 위험한 것이기도 하다.","paragraph":0,"memberIds":["R02:1"],"topic":"게다가 사랑은 위험한 것이기도 하다."},{"id":"R02:2","text":"많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.","paragraph":0,"memberIds":["R02:2"],"topic":"성숙한 사랑은 상대만의 개성과 됨됨이(인격)를 존중한다. 그런데 많은 사랑은 그런 모습이 아니다. 사실은 상대를 통해 내 욕심(욕망)을 이루려고 매달리는 집착의 모습이다."},{"id":"R02:3","text":"부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.","paragraph":0,"memberIds":["R02:3"],"topic":"부모는 자녀가 무엇을 잘하는지(적성), 어떤 사람인지(개성), 무엇을 바라는지(소망)를 생각하지 않고, 자기가 바라는 것을 자녀에게 억지로 시키곤 한다."},{"id":"R02:4","text":"연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.","paragraph":0,"memberIds":["R02:4"],"topic":"연인을 사랑할 때도 연인을 내 것으로 갖고(소유) 내 마음대로 하고 싶은(지배) 욕심이 끼어들기(개입되기) 쉽다."},{"id":"R02:5","text":"그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.","paragraph":0,"memberIds":["R02:5"],"topic":"그래서 우리는 사랑으로 서로 자라고(성숙하고) 함께 행복해지기보다, 사랑 때문에 힘들어하고 슬퍼하고 좌절하는 경우가 많다."}]}]},"id":"U31-P02-03-S1","type":"mc","sent":"2문단의 내용과 맞는 설명은?","options":["연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.","연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심은 생길 수 없다.","많은 사람은 상대를 사랑할 때 자기 욕심을 전혀 채우려 하지 않는다.","부모는 자신이 원하는 것을 버리고 자녀가 원하는 것을 존중한다.","상대에게 집착하면 사랑 때문에 행복해하고 만족하는 경우가 많다."],"answer":"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.","choiceReviews":{"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.":{"reason":"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n근거: “연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.”\n2문단에서 확인할 수 있어요.","edits":[]},"연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심은 생길 수 없다.":{"reason":"바르게 고치면: 연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n연인을 자기 것으로 여기거나 자기 마음대로 하려는 욕심이 생기기 쉽다.\n근거: “연인에 대한 사랑에도 연인을 소유하고 지배하고 싶어 하는 욕망이 개입되기 쉽다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":28,"end":40,"before":"욕심은 생길 수 없다.","after":"욕심이 생기기 쉽다."}]},"많은 사람은 상대를 사랑할 때 자기 욕심을 전혀 채우려 하지 않는다.":{"reason":"바르게 고치면: 많은 사람은 상대를 사랑한다면서 자기 욕심을 채우려 한다.\n글쓴이는 상대를 존중하는 사랑과 자기 욕심을 채우려는 집착을 다르게 본다. 상대를 통해 자기 뜻만 이루려 한다면 집착이다.\n근거: “많은 사랑이 상대방의 개성과 고유한 인격을 존중하는 성숙한 형태가 아니라, 사실은 사랑하는 상대를 통해서 자신의 욕망을 구현하고 싶어 하는 집착의 형태를 띤다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":11,"end":17,"before":"사랑할 때 ","after":"사랑한다면서 "},{"start":24,"end":27,"before":"전혀 ","after":""},{"start":31,"end":38,"before":"하지 않는다.","after":"한다."}]},"부모는 자신이 원하는 것을 버리고 자녀가 원하는 것을 존중한다.":{"reason":"바르게 고치면: 부모는 자녀가 원하는 것을 무시하고 자신이 원하는 것을 강요한다.\n이 사례에서 부모는 자녀의 적성이나 개성, 소망을 고려하지 않는다. 자녀에게 부모 자신의 욕심을 강요한다.\n근거: “부모는 자녀의 적성이나 개성 그리고 소망을 고려하지 않고 자녀에게 자신의 욕망을 강요하고는 한다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":0,"end":4,"before":"부모는 ","after":"부모는 자녀가 원하는 것을 무시하고 "},{"start":15,"end":35,"before":"버리고 자녀가 원하는 것을 존중한다.","after":"강요한다."}]},"상대에게 집착하면 사랑 때문에 행복해하고 만족하는 경우가 많다.":{"reason":"바르게 고치면: 상대에게 집착하면 사랑 때문에 힘들어하고 좌절하는 경우가 많다.\n상대에게 집착하면 사랑 때문에 힘들어하고 좌절하는 경우가 많다.\n근거: “그 결과 우리는 사랑을 통해서 서로 성숙하고 함께 행복하기보다는 사랑으로 인해 힘들어하고 슬픔과 좌절에 빠지는 경우가 많다.”\n2문단에서 확인할 수 있어요.","edits":[{"start":17,"end":28,"before":"행복해하고 만족하는 ","after":"힘들어하고 좌절하는 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"dbb4fa8a6a4d8339a1123695757702f922705699ef2d182f70cd629dc47e3f11"}]},{"name":"U31-P03-01-S1 · 정도","items":[{"paragraphCount":1,"readingLabel":"3문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 3문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 3문단]\n그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다. 그리고 사랑하는 방법도 이미 잘 알고 있어서 배울 필요가 없다고 생각한다. 우리는 과연 사랑에 대해서 잘 알고 있는가?","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["정도"],"why":"사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","evidence":{"title":"사람들은 사랑을 뻔하게 여긴다.","statement":"사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.","explanation":"사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","valid":["R03:1"],"sources":[{"id":"R03","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"3문단","sentences":[{"id":"R03:1","text":"그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.","paragraph":0,"memberIds":["R03:1"],"topic":"그런데도 우리는 사랑을 '너무 뻔한 것(자명한 현상)'이라고 생각한다. 진지하게 파고들(탐구할) 필요도 없다고 여긴다."},{"id":"R03:2","text":"그리고 사랑하는 방법도 이미 잘 알고 있어서 배울 필요가 없다고 생각한다.","paragraph":0,"memberIds":["R03:2"],"topic":"그리고 사랑하는 방법도 이미 잘 알고 있으니 배울 필요가 없다고 생각한다."},{"id":"R03:3","text":"우리는 과연 사랑에 대해서 잘 알고 있는가?","paragraph":0,"memberIds":["R03:3"],"topic":"그런데 우리는 정말 사랑에 대해 잘 알고 있을까?"}]}]},"id":"U31-P03-01-S1","type":"mc","sent":"3문단의 내용과 맞는 설명은?","options":["사람들은 사랑을 낯설게 느낀다. 그래서 깊이 알아보아야 한다고 여긴다.","사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.","사람들은 사랑하는 방법을 전혀 모른다고 생각한다. 그래서 반드시 새로 배워야 한다고 여긴다.","글쓴이는 마지막에 '우리는 사랑을 정말 잘 알고 있다'고 확신한다.","사람들은 사랑을 너무 복잡한 일로 여겨 자세히 알아봐야만 이해할 수 있다고 생각한다."],"answer":"사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.","choiceReviews":{"사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.":{"reason":"사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[]},"사람들은 사랑을 낯설게 느낀다. 그래서 깊이 알아보아야 한다고 여긴다.":{"reason":"바르게 고치면: 사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n사람들은 사랑을 이미 잘 안다고 생각한다. 그래서 깊이 알아볼 필요도 없다고 여긴다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[{"start":9,"end":18,"before":"낯설게 느낀다. ","after":"이미 잘 안다고 생각한다. "},{"start":25,"end":35,"before":"알아보아야 한다고 ","after":"알아볼 필요도 없다고 "}]},"사람들은 사랑하는 방법을 전혀 모른다고 생각한다. 그래서 반드시 새로 배워야 한다고 여긴다.":{"reason":"바르게 고치면: 사람들은 사랑하는 방법을 이미 잘 안다고 생각한다. 그래서 따로 배울 필요가 없다고 여긴다.\n사람들은 사랑하는 방법을 이미 잘 안다고 생각한다. 그래서 따로 배울 필요가 없다고 여긴다.\n근거: “그리고 사랑하는 방법도 이미 잘 알고 있어서 배울 필요가 없다고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[{"start":14,"end":22,"before":"전혀 모른다고 ","after":"이미 잘 안다고 "},{"start":32,"end":47,"before":"반드시 새로 배워야 한다고 ","after":"따로 배울 필요가 없다고 "}]},"글쓴이는 마지막에 '우리는 사랑을 정말 잘 알고 있다'고 확신한다.":{"reason":"바르게 고치면: 글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n글쓴이는 마지막에 '우리가 사랑을 정말 잘 알고 있을까?'라고 묻는다.\n근거: “우리는 과연 사랑에 대해서 잘 알고 있는가?”\n3문단에서 확인할 수 있어요.","edits":[{"start":10,"end":15,"before":"'우리는 ","after":"'우리가 "},{"start":27,"end":37,"before":"있다'고 확신한다.","after":"있을까?'라고 묻는다."}]},"사람들은 사랑을 너무 복잡한 일로 여겨 자세히 알아봐야만 이해할 수 있다고 생각한다.":{"reason":"바르게 고치면: 사람들은 사랑을 너무 당연한 일로 여겨 자세히 알아볼 필요가 없다고 생각한다.\n이 문단의 '자명하다'는 너무 당연하고 분명하다는 뜻이다. 사람들은 사랑을 이미 잘 안다고 생각한다.\n근거: “그럼에도 우리는 사랑이란 진지하게 탐구할 필요가 없을 정도로 자명한 현상이라고 생각한다.”\n3문단에서 확인할 수 있어요.","edits":[{"start":12,"end":16,"before":"복잡한 ","after":"당연한 "},{"start":26,"end":42,"before":"알아봐야만 이해할 수 있다고 ","after":"알아볼 필요가 없다고 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"9eb1bf88708c118c3b685fdff2c3c416593bd2ae42e08924ab1030ecc0ef1ed4"}]},{"name":"U31-P14-01-S1 · 정도","items":[{"paragraphCount":1,"readingLabel":"14문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 14문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 14문단]\n나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다. 예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다. 그들은 자신들만의 이기적인 사랑을 추구하지 않는다. 사랑하는 두 연인은 자신들의 사랑이 다른 사람들의 행복에 기여하는 것이 되기를 바란다. 그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["정도"],"why":"성숙한 사랑은 한 사람에게만 머무르지 않는다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.”\n14문단에서 확인할 수 있어요.","evidence":{"title":"성숙한 사랑은 한 사람에 갇히지 않는다.","statement":"성숙한 사랑은 한 사람에게만 머무르지 않는다.","explanation":"성숙한 사랑은 한 사람에게만 머무르지 않는다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.”\n14문단에서 확인할 수 있어요.","valid":["R14:1"],"sources":[{"id":"R14","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"14문단","sentences":[{"id":"R14:1","text":"나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.","paragraph":0,"memberIds":["R14:1"],"topic":"더 나아가 성숙한 사랑은 절대 한 사람에게만 머무르지(제한되지) 않는다."},{"id":"R14:2","text":"예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.","paragraph":0,"memberIds":["R14:2"],"topic":"예를 들어 두 연인이 진짜로 사랑하고, 부모가 진짜로 자녀를 사랑한다고 하자. 그렇다고 그들이 다른 사람들에게 관심을 끊는(무관심해지는) 것은 아니다."},{"id":"R14:3","text":"그들은 자신들만의 이기적인 사랑을 추구하지 않는다.","paragraph":0,"memberIds":["R14:3"],"topic":"그들은 자기들끼리만 챙기는 이기적인 사랑을 바라지(추구하지) 않는다."},{"id":"R14:4","text":"사랑하는 두 연인은 자신들의 사랑이 다른 사람들의 행복에 기여하는 것이 되기를 바란다.","paragraph":0,"memberIds":["R14:4"],"topic":"사랑하는 두 연인은 자기들의 사랑이 다른 사람들의 행복에도 도움이 되기를(기여하기를) 바란다."},{"id":"R14:5","text":"그리고 자식을 사랑하는 부모는 자식이 이기적인 인간이 아니라 남을 도울 수 있는 훌륭한 인간이 되기를 바란다.","paragraph":0,"memberIds":["R14:5"],"topic":"그리고 자식을 사랑하는 부모는 자식이 이기적인 사람이 아니라, 남을 도울 수 있는 훌륭한 사람이 되기를 바란다."}]}]},"id":"U31-P14-01-S1","type":"mc","sent":"14문단의 내용과 맞는 설명은?","options":["성숙한 사랑은 한 사람에게만 머무른다.","성숙한 사랑은 한 사람에게만 머무르지 않는다.","진정으로 사랑하는 연인은 다른 사람들에게 관심을 두지 않는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.","진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각한다.","서로 사랑하는 두 연인은 다른 사람들이 자신들의 사랑으로 더 불행해지기를 바란다."],"answer":"성숙한 사랑은 한 사람에게만 머무르지 않는다.","choiceReviews":{"성숙한 사랑은 한 사람에게만 머무르지 않는다.":{"reason":"성숙한 사랑은 한 사람에게만 머무르지 않는다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.”\n14문단에서 확인할 수 있어요.","edits":[]},"성숙한 사랑은 한 사람에게만 머무른다.":{"reason":"바르게 고치면: 성숙한 사랑은 한 사람에게만 머무르지 않는다.\n성숙한 사랑은 한 사람에게만 머무르지 않는다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":16,"end":21,"before":"머무른다.","after":"머무르지 않는다."}]},"진정으로 사랑하는 연인은 다른 사람들에게 관심을 두지 않는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.":{"reason":"바르게 고치면: 진정으로 사랑하는 연인은 다른 사람들에게도 관심을 갖는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.\n진정으로 사랑하는 연인은 다른 사람들에게도 관심을 갖는다. 자녀를 진정으로 사랑하는 부모도 마찬가지다.\n근거: “예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":17,"end":23,"before":"사람들에게 ","after":"사람들에게도 "},{"start":27,"end":35,"before":"두지 않는다. ","after":"갖는다. "}]},"진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각한다.":{"reason":"바르게 고치면: 진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각하지 않는다.\n진정으로 사랑하는 사람들은 자기들만 잘되면 된다고 생각하지 않는다.\n근거: “그들은 자신들만의 이기적인 사랑을 추구하지 않는다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":28,"end":33,"before":"생각한다.","after":"생각하지 않는다."}]},"서로 사랑하는 두 연인은 다른 사람들이 자신들의 사랑으로 더 불행해지기를 바란다.":{"reason":"바르게 고치면: 서로 사랑하는 두 연인은 다른 사람들도 자신들의 사랑으로 더 행복해지기를 바란다.\n서로 사랑하는 두 연인은 다른 사람들도 자신들의 사랑으로 더 행복해지기를 바란다.\n근거: “사랑하는 두 연인은 자신들의 사랑이 다른 사람들의 행복에 기여하는 것이 되기를 바란다.”\n14문단에서 확인할 수 있어요.","edits":[{"start":17,"end":22,"before":"사람들이 ","after":"사람들도 "},{"start":34,"end":41,"before":"불행해지기를 ","after":"행복해지기를 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"875bbc45ed009f6f47aec68aa5434420921b22d4a0b008537c0422bd6863e63d"}]},{"name":"U31-P15-01-S1 · 정도","items":[{"paragraphCount":1,"readingLabel":"15문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 15문단]\n따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다. 어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다. 어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다. 진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["정도"],"why":"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.\n근거: “따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.”\n15문단에서 확인할 수 있어요.","evidence":{"title":"사랑은 세계 전체를 대하는 태도이다.","statement":"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.","explanation":"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.\n근거: “따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.”\n15문단에서 확인할 수 있어요.","valid":["R15:1"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:1","text":"따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.","paragraph":0,"memberIds":["R15:1"],"topic":"그러니 성숙한 사랑은 '한' 사람, '하나의' 대상을 대하는 태도가 아니다. 세상 전체와 어떻게 관계를 맺을지 정하는 '태도', 곧 그 사람이 가진 '특정한 성격'이다."},{"id":"R15:2","text":"어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.","paragraph":0,"memberIds":["R15:2"],"topic":"어떤 사람을 진짜로 사랑한다는 것은 그 사람의 인간으로서의 핵심과 관계를 맺는 것이다. 즉 그 사람을 '인류와 삶을 대표하는 한 사람'으로 대하는 것이다."},{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."},{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"id":"U31-P15-01-S1","type":"mc","sent":"15문단의 내용과 맞는 설명은?","options":["성숙한 사랑은 특정한 한 사람만 대하는 태도다. 세상 전체와는 관계가 없다.","어떤 사람을 진정으로 사랑할 때는 그 사람과만 관계를 맺으며 다른 사람들의 삶에는 관심을 두지 않는다.","한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없어도, 그 사랑은 성숙한 사랑이다.","성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.","한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊더라도, 그것은 이기적인 사랑이 아니다."],"answer":"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.","choiceReviews":{"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.":{"reason":"성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.\n근거: “따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.”\n15문단에서 확인할 수 있어요.","edits":[]},"성숙한 사랑은 특정한 한 사람만 대하는 태도다. 세상 전체와는 관계가 없다.":{"reason":"바르게 고치면: 성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.\n성숙한 사랑은 세상 전체를 대하는 태도다. 특정한 한 사람에게만 향하는 감정이 아니다.\n근거: “따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":4,"end":8,"before":"사랑은 ","after":"사랑은 세상 전체를 대하는 태도다. "},{"start":14,"end":42,"before":"사람만 대하는 태도다. 세상 전체와는 관계가 없다.","after":"사람에게만 향하는 감정이 아니다."}]},"어떤 사람을 진정으로 사랑할 때는 그 사람과만 관계를 맺으며 다른 사람들의 삶에는 관심을 두지 않는다.":{"reason":"바르게 고치면: 어떤 사람을 진정으로 사랑할 때는 그 사람을 인류와 삶을 대표하는 한 사람으로 보고 관계를 맺는다.\n글쓴이는 상대의 '인간적인 핵심'과 관계한다고 말했다. 그 사람을 인류와 삶을 대표하는 한 사람으로 보고 사랑한다는 뜻이다. 그래서 한 사람을 사랑하는 일을 다른 사람들의 삶과 따로 떼어 보지 않는다.\n근거: “어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":21,"end":26,"before":"사람과만 ","after":"사람을 인류와 삶을 대표하는 한 사람으로 보고 "},{"start":30,"end":57,"before":"맺으며 다른 사람들의 삶에는 관심을 두지 않는다.","after":"맺는다."}]},"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없어도, 그 사랑은 성숙한 사랑이다.":{"reason":"바르게 고치면: 한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":28,"end":33,"before":"없어도, ","after":"없다면, "},{"start":39,"end":43,"before":"성숙한 ","after":"깊이 없는 "}]},"한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊더라도, 그것은 이기적인 사랑이 아니다.":{"reason":"바르게 고치면: 한 사람만 사랑하고 다른 사람들의 삶에는 관심을 끊는다면, 결국 둘만 생각하는 이기적인 사랑이다.\n'확대된 이기주의'는 자기만 챙기던 마음이 사랑하는 상대까지만 넓어진 것이다. 다른 사람들의 삶에는 여전히 관심을 두지 않는다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","edits":[{"start":27,"end":37,"before":"끊더라도, 그것은 ","after":"끊는다면, 결국 둘만 생각하는 "},{"start":42,"end":50,"before":"사랑이 아니다.","after":"사랑이다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"9531a9fbee8ffe29a22e00813ec02bc321c71d37c164cf6e27d7cc968b253135"}]}]};})(window);
